  1	/**
  2	 * El access token de una conexión, refrescado una sola vez aunque lo pidan
  3	 * varios a la vez. Con conexión, los que llegan mientras hay un refresco en
  4	 * curso lo comparten aunque cada uno haya cargado un refresh token distinto;
  5	 * sin ella, se comparte por refresh token. Cada refresco pasa por el carril
  6	 * de su familia; antes de presentar un token se comprueba que no se haya
  7	 * rotado ya y que la fila guardada no tenga uno más nuevo. El guardado ocurre
  8	 * dentro de la misma ventana, antes de que nadie más vea el resultado, y no
  9	 * pisa una fila que otro escritor ya rotó.
 10	 *
 11	 * Porte de `getAccessToken`, `_getAccessTokenWithStalenessCheck`,
 12	 * `_refreshWithFreshCredentials`, `getAllAccessTokens` y
 13	 * `getConnectionRefreshMutexStatus` de `omniroute: open-sse/services/tokenRefresh.ts` (MIT).
 14	 */
 15	import { casGuardShouldSkipPersist } from './casGuard.ts'
 16	import { activePersist, type RefreshPersistFn } from './persistContext.ts'
 17	import type { ProviderRefreshOutcome, RefreshCredentials } from './providerRefreshDispatch.ts'
 18	import type { RefreshLogger } from './refreshErrors.ts'
 19	import { createRefreshSerializer, type RefreshSerializer } from './refreshSerializer.ts'
 20	import { createRotationMap, refreshCacheKey, type RotatedTokens } from './rotationMap.ts'
 21	
 22	/** Una fila guardada vigente al menos este margen se usa tal cual. */
 23	const STORED_TOKEN_MIN_VALIDITY_MS = 60_000
 24	
 25	export interface StoredConnectionTokens {
 26	  refreshToken?: string | null
 27	  accessToken?: string | null
 28	  expiresAt?: string | null
 29	}
 30	
 31	export interface AccessTokenCredentials extends RefreshCredentials {
 32	  accessToken?: string
 33	}
 34	
 35	export interface TokenRefresherDeps {
 36	  refresh: (provider: string, credentials: RefreshCredentials) => Promise<ProviderRefreshOutcome>
 37	  serialize?: RefreshSerializer
 38	  rotations?: ReturnType<typeof createRotationMap>
 39	  /** La fila guardada de una conexión, descifrada. */
 40	  readConnection?: (connectionId: string) => StoredConnectionTokens | null | undefined | Promise<StoredConnectionTokens | null | undefined>
 41	  now?: () => number
 42	  log?: RefreshLogger
 43	}
 44	
 45	export interface ConnectionTokenSource {
 46	  provider?: string
 47	  refreshToken?: string
 48	  isActive?: boolean
 49	}
 50	
 51	const hasAccessToken = (result: ProviderRefreshOutcome | StoredConnectionTokens): result is Record<string, unknown> & { accessToken: string } => Boolean(result && 'accessToken' in result && result.accessToken)
 52	const errorMessage = (error: unknown) => (error instanceof Error ? error.message : String(error))
 53	
 54	export function createTokenRefresher(deps: TokenRefresherDeps) {
 55	  const serialize = deps.serialize ?? createRefreshSerializer()
 56	  const rotations = deps.rotations ?? createRotationMap({ now: deps.now })
 57	  const now = deps.now ?? Date.now
 58	  const { log } = deps
 59	  const connectionMutex = new Map<string, { promise: Promise<ProviderRefreshOutcome>; waiters: number }>()
 60	  const inFlightByToken = new Map<string, Promise<ProviderRefreshOutcome>>()
 61	
 62	  /** La fila guardada gana si tiene otro refresh token: vigente, se usa; por caducar, es la que se refresca. */
 63	  async function refreshWithFreshCredentials(provider: string, credentials: AccessTokenCredentials): Promise<ProviderRefreshOutcome> {
 64	    const rotated = rotations.lookup(provider, credentials.refreshToken)
 65	    if (rotated) {
 66	      log?.info?.('TOKEN_REFRESH', `Rotation map hit for ${provider}. Returning cached rotated tokens (avoids family-revoke).`)
 67	      return rotated.result as ProviderRefreshOutcome
 68	    }
 69	    let current = credentials
 70	    if (credentials.connectionId && deps.readConnection) {
 71	      try {
 72	        const stored = await deps.readConnection(credentials.connectionId)
 73	        if (stored?.refreshToken && stored.refreshToken !== credentials.refreshToken) {
 74	          log?.info?.('TOKEN_REFRESH', `Stale token detected in memory for ${provider}. Using refreshed token from DB.`)
 75	          const storedExpiresAt = stored.expiresAt ? new Date(stored.expiresAt).getTime() : 0
 76	          if (storedExpiresAt > now() + STORED_TOKEN_MIN_VALIDITY_MS) {
 77	            log?.info?.('TOKEN_REFRESH', 'DB token is still valid. Skipping OAuth refresh.')
 78	            return { accessToken: stored.accessToken as string, refreshToken: stored.refreshToken, expiresAt: stored.expiresAt }
 79	          }
 80	          current = { ...credentials, refreshToken: stored.refreshToken, accessToken: stored.accessToken ?? undefined }
 81	        }
 82	      } catch (error) {
 83	        log?.warn?.('TOKEN_REFRESH', `Failed to check DB for stale token: ${errorMessage(error)}`)
 84	      }
 85	    }
 86	    const result = await deps.refresh(provider, current)
 87	    if (hasAccessToken(result) && result.refreshToken && !('error' in result)) rotations.record(provider, current.refreshToken, result as unknown as RotatedTokens)
 88	    return result
 89	  }
 90	
 91	  /** El refresco en el carril de su familia: la comprobación de frescura va dentro, justo antes de la red. */
 92	  const refreshInLane = (provider: string, credentials: AccessTokenCredentials) => serialize(provider, () => refreshWithFreshCredentials(provider, credentials))
 93	
 94	  async function persistResult(result: ProviderRefreshOutcome, persist: RefreshPersistFn | undefined, failureContext: string): Promise<ProviderRefreshOutcome> {
 95	    if (!hasAccessToken(result) || !persist) return result
 96	    if (await casGuardShouldSkipPersist(log)) return result
 97	    try {
 98	      await persist(result)
 99	    } catch (error) {
100	      log?.error?.('TOKEN_REFRESH', `${failureContext}: ${errorMessage(error)}`)
101	      throw error
102	    }
103	    return result
104	  }
105	
106	  async function getAccessToken(provider: string, credentials: AccessTokenCredentials | null | undefined, persist?: RefreshPersistFn): Promise<ProviderRefreshOutcome> {
107	    if (!credentials || typeof credentials.refreshToken !== 'string' || !credentials.refreshToken) {
108	      log?.warn?.('TOKEN_REFRESH', `No valid refresh token available for provider: ${provider}`)
109	      return null
110	    }
111	    const effectivePersist = persist ?? activePersist()
112	    const { connectionId } = credentials
113	
114	    if (connectionId && typeof connectionId === 'string') {
115	      const existing = connectionMutex.get(connectionId)
116	      if (existing) {
117	        existing.waiters++
118	        log?.info?.('TOKEN_REFRESH', 'Concurrent refresh detected — sharing in-flight refresh', { provider, connectionId, waiters: existing.waiters })
119	        return existing.promise
120	      }
121	      const promise = refreshInLane(provider, credentials)
122	        .then(result => persistResult(result, effectivePersist, `onPersist callback failed for ${provider}/${connectionId}`))
123	        .finally(() => connectionMutex.delete(connectionId))
124	      connectionMutex.set(connectionId, { promise, waiters: 0 })
125	      return promise
126	    }
127	
128	    const cacheKey = refreshCacheKey(provider, credentials.refreshToken)
129	    const inFlight = inFlightByToken.get(cacheKey)
130	    if (inFlight) {
131	      log?.info?.('TOKEN_REFRESH', `Reusing in-flight refresh for ${provider}`)
132	      return inFlight
133	    }
134	    const promise = refreshInLane(provider, credentials)
135	      .then(result => {
136	        if (hasAccessToken(result) && !effectivePersist) {
137	          log?.warn?.('TOKEN_REFRESH', `Layer 2 refresh succeeded for ${provider} without onPersist — DB row will not be updated with rotated token. Callers should pass connectionId for Layer 1 atomicity.`)
138	        }
139	        return persistResult(result, effectivePersist, `Layer 2 onPersist callback failed for ${provider}`)
140	      })
141	      .finally(() => inFlightByToken.delete(cacheKey))
142	    inFlightByToken.set(cacheKey, promise)
143	    return promise
144	  }
145	
146	  /** El token de cada conexión activa con proveedor, por proveedor. */
147	  async function getAllAccessTokens(connections: readonly ConnectionTokenSource[] | null | undefined): Promise<Record<string, ProviderRefreshOutcome>> {
148	    const results: Record<string, ProviderRefreshOutcome> = {}
149	    for (const connection of connections ?? []) {
150	      if (!connection.isActive || !connection.provider) continue
151	      const token = await getAccessToken(connection.provider, { refreshToken: connection.refreshToken as string })
152	      if (token) results[connection.provider] = token
153	    }
154	    return results
155	  }
156	
157	  function connectionMutexStatus(): Record<string, { waiters: number }> {
158	    return Object.fromEntries([...connectionMutex].map(([connectionId, entry]) => [connectionId, { waiters: entry.waiters }]))
159	  }
160	
161	  return { getAccessToken, getAllAccessTokens, connectionMutexStatus }
162	}

